// Generates the CSS theme files from src/index.ts. Run from the repo root:
// `pnpm tokens:build`. Outputs are committed so builds don't need to run this.
//
//   tokens.css   website: :root / .dark variables (imported by app/globals.css)
//   uniwind.css  mobile app: Uniwind theme (imported by mobile/src/global.css)

import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { colors, fontFamily, radius, radiusBase } from "../src/index";

const header = [
  "/* Generated by packages/tokens/scripts/build-css.ts — do not edit by hand.",
  "   Edit packages/tokens/src/index.ts, then run `pnpm tokens:build`. */\n",
].join("\n");

function vars(entries: Record<string, string | number>, prefix: string, indent: string) {
  return Object.entries(entries)
    .map(([name, value]) => `${indent}--${prefix}${name}: ${value};`)
    .join("\n");
}

function write(file: string, css: string) {
  const out = fileURLToPath(new URL(`../${file}`, import.meta.url));
  writeFileSync(out, css);
  console.log(`Wrote ${out}`);
}

// Website: same variable names shadcn/Tailwind expect; globals.css maps them
// to utilities with @theme inline.
write(
  "tokens.css",
  [
    header,
    `:root {\n${vars({ ...colors.light, radius: `${radiusBase / 16}rem` }, "", "  ")}\n}\n`,
    `.dark {\n${vars(colors.dark, "", "  ")}\n}\n`,
  ].join("\n"),
);

// Mobile app: Uniwind reads themed colours from @variant blocks and maps
// --color-* to utilities directly (bg-primary, text-muted-foreground, …).
// Radius and font families are fixed values, so they go in @theme.
const fonts = {
  sans: fontFamily.regular,
  "sans-light": fontFamily.light,
  "sans-italic": fontFamily.italic,
  "sans-medium": fontFamily.medium,
  "sans-medium-italic": fontFamily.mediumItalic,
  "sans-bold": fontFamily.bold,
  "sans-heavy": fontFamily.heavy,
};
write(
  "uniwind.css",
  [
    header,
    "@layer theme {",
    "  :root {",
    `    @variant light {\n${vars(colors.light, "color-", "      ")}\n    }\n`,
    `    @variant dark {\n${vars(colors.dark, "color-", "      ")}\n    }`,
    "  }",
    "}\n",
    "@theme {",
    vars(Object.fromEntries(Object.entries(radius).map(([k, v]) => [k, `${v}px`])), "radius-", "  "),
    vars(fonts, "font-", "  "),
    "}\n",
  ].join("\n"),
);
